        return level
    return max(current, level) if side > 0 else min(current, level)


def nearer_take(current, level, side):
    if current is None:
        return level
    return min(current, level) if side > 0 else max(current, level)


def strategy(hist, state, pos, ind):
    close = hist.close
    high = hist.high
    low = hist.low
    t = len(close) - 1
    price = close[-1]
    atr = ind.atr(hist, 14)[-1]
    side = 1 if pos > 0 else (-1 if pos < 0 else 0)

    # entry signal
    box_top = ind.highest(high, 16)[-1]
    box_bot = ind.lowest(low, 16)[-1]
    sig = 0
    if box_top - box_bot <= 4.0 * atr:
        if price > box_top:
            sig = 1
        elif price < box_bot:
            sig = -1

    # a trade we opened is over (exit order filled, closed, or never filled)
    if "side" in state and state["side"] != side:
        state["cool_until"] = t + 96
        for key in ('side', 'ref', 'ref_atr', 'shift'):
            if key in state:
                del state[key]

    target = 0.0
    if side == 0:
        if sig > 0:
            ok = True
            if "cool_until" in state:
                if t < state["cool_until"]:
                    ok = False
                else:
                    del state["cool_until"]
            if ok:
                size = min(1.0, max(0.05, 0.01 * price / (3.0 * atr)))
                state["side"] = sig
                state["ref"] = price
                state["ref_atr"] = atr
                state["shift"] = 0
                target = sig * size
    else:
        target = pos
        while side * (price - state["ref"]) >= (state["shift"] + 1) * 1.0 * state["ref_atr"]:
            state["shift"] = state["shift"] + 1
        if sig == -side:
            target = 0.0

    stop = None
    take = None
    if "side" in state:
        s = state["side"]
        ref = state["ref"]
        ra = state["ref_atr"]
        anchor = ref + s * state["shift"] * 1.0 * ra
        stop = tighter_stop(stop, anchor - s * 2.0 * ra, s)
        take = nearer_take(take, anchor + s * 3.0 * ra, s)
    return {"target": target, "stop": stop, "take": take}

